'use strict';
const M=Arith,$=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let view='inverse',rsaKey=null;
const config={inverse:{title:'Inverse modulaire',text:'Entrez a et n pour trouver l’entier x tel que a × x ≡ 1 (mod n).'},euclide:{title:'Euclide & Bézout',text:'Calculez le PGCD, le PPCM et les coefficients de Bézout de deux entiers.'},euler:{title:'Indicatrice d’Euler',text:'Décomposez n en facteurs premiers pour calculer le nombre d’entiers premiers avec n.'},rsa:{title:'Chiffrement RSA',text:'Choisissez deux nombres premiers, construisez vos clés et chiffrez ou déchiffrez un message.'}};
const field=(id,title,hint,value)=>`<label for="${id}">${title}<small>${hint}</small><input id="${id}" name="${id}" inputmode="numeric" autocomplete="off" value="${value}" required></label>`;
const examples=items=>`<div class="examples">Essayer : ${items.map(([label,values])=>`<button type="button" data-example="${values}">${label}</button>`).join('')}</div>`;
const submit=label=>`<button class="primary" type="submit">${label}<span>→</span></button>`;
const step=(title,body)=>`<div class="step"><h3>${title}</h3>${body}</div>`;
const eq=s=>`<div class="equation">${s}</div>`;
const answer=(label,big,note,fail=false)=>`<div class="answer${fail?' fail':''}"><div class="answer-label"><span>${label}</span><span>${fail?'∅':'✓'}</span></div><div class="big">${big}</div><p>${note}</p></div>`;
function val(id){return M.integer($('#'+id).value,id);}
function showError(err){$('#result').innerHTML=`<div class="error" role="alert">${esc(err.message)}</div>`;}
function divisions(rows){return rows.map(r=>eq(`${r.a} = ${r.b} × ${r.q} + <strong>${r.r}</strong>`)).join('');}
function bezoutTable(a,b){let r=M.abs(a),s=M.abs(b),x=1n,y=0n,u=0n,v=1n;let rows=[[r,x*(a<0n?-1n:1n),y],[s,u,v*(b<0n?-1n:1n)]];while(s){let q=r/s;[r,s]=[s,r-q*s];[x,u]=[u,x-q*u];[y,v]=[v,y-q*v];if(s)rows.push([s,u*(a<0n?-1n:1n),v*(b<0n?-1n:1n)]);}return `<details><summary>Voir la construction des coefficients de Bézout</summary><p>À chaque division : nouvelle ligne = ligne précédente − quotient × ligne actuelle. Chaque ligne vérifie r = a × u + b × v.</p><div class="table-wrap"><table><thead><tr><th>r</th><th>u</th><th>v</th></tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>`;}
function renderInverse(){const a=val('a'),n=val('n'),z=M.inverse(a,n);if(z.value===null){$('#result').innerHTML=answer('CONDITION NON VÉRIFIÉE','Pas d’inverse.',`PGCD(${a}, ${n}) = ${z.g} ≠ 1. Ces nombres ne sont pas premiers entre eux.`,true)+`<div class="steps">${step('Calculer le PGCD',divisions(z.rows))}${step('Conclure',`<p>Un inverse existe si et seulement si le PGCD vaut 1. Aucun entier x ne vérifie ${a}x ≡ 1 (mod ${n}).</p>`)}</div>`;return;}
 let extra='';if(n<=1000000000000n){const ph=M.phi(n);extra=`<details><summary>Retrouver l’inverse avec ${M.prime(n)?'Fermat':'Euler'}</summary><p>φ(${n}) = ${ph}. Comme le PGCD vaut 1, a<sup>φ(n) − 1</sup> donne le même inverse.</p>${eq(`${a}<sup>${ph-1n}</sup> ≡ ${z.value} (mod ${n})`)}</details>`;}
 $('#result').innerHTML=answer('L’INVERSE EXISTE',`${a}<sup>−1</sup> ≡ ${z.value} <small>(mod ${n})</small>`,`PGCD(${a}, ${n}) = 1 · Les deux nombres sont premiers entre eux.`)+`<div class="steps">${step('Descendre avec Euclide',divisions(z.rows))}${step('Retrouver l’identité de Bézout',eq(`${a} × (${z.x}) + ${n} × (${z.y}) = 1`)+`<p>Le coefficient de ${a} est ${z.x} : c’est un inverse modulo ${n}.</p>`+bezoutTable(a,n))}${step('Choisir le représentant positif',eq(`${z.x} ≡ <strong>${z.value}</strong> (mod ${n})`)+`<p>On ramène le résultat dans l’intervalle de 0 à ${n-1n}.</p>`)}</div><div class="verification">✓ Vérification : ${a} × ${z.value} = ${a*z.value} ≡ 1 (mod ${n})</div>${extra}`;}
function renderEuclide(){const a=val('a'),b=val('b');if(a===0n&&b===0n)throw Error('Choisissez au moins un entier non nul.');const z=M.egcd(a,b),l=M.abs(a*b)/z.g;let division=b!==0n?eq(`${a} = ${b} × ${(a-M.mod(a,M.abs(b)))/b} + ${M.mod(a,M.abs(b))}`):'<p>La division par zéro n’est pas définie.</p>';$('#result').innerHTML=answer('LE PLUS GRAND COMMUN DIVISEUR',`PGCD(${a}, ${b}) = ${z.g}`,z.g===1n?'Ces nombres sont premiers entre eux.':`Leur plus grand diviseur commun est ${z.g}.`)+`<div class="steps">${step('La division euclidienne de a par b',division)}${step('Les divisions successives',divisions(z.rows)||'<p>Un entier est nul : le PGCD est la valeur absolue de l’autre.</p>')}${step('L’identité de Bézout',eq(`${a} × (${z.x}) + ${b} × (${z.y}) = ${z.g}`)+bezoutTable(a,b))}${step('Le plus petit commun multiple',eq(`PPCM(${a}, ${b}) = |a × b| / PGCD = <strong>${l}</strong>`))}</div>`;}
function renderEuler(){const n=val('n'),f=M.factors(n),ph=M.phi(n);$('#result').innerHTML=answer('L’INDICATRICE D’EULER',`φ(${n}) = ${ph}`,`Il y a ${ph} entier${ph>1n?'s':''} entre 1 et ${n} premier${ph>1n?'s':''} avec ${n}.`)+`<div class="steps">${step('Décomposer en facteurs premiers',eq(`${n} = ${f.length?f.map(([p,k])=>`${p}${k>1?`<sup>${k}</sup>`:''}`).join(' × '):'1'}`))}${step('Appliquer la formule d’Euler',eq(`φ(${n}) = ${n}${f.map(([p])=>` × (1 − 1/${p})`).join('')} = <strong>${ph}</strong>`)+`<p>On utilise chaque facteur premier distinct une seule fois.${n===1n?' Par convention, φ(1) = 1.':''}</p>`)}${step('Interpréter le résultat',n<=100n?`<p>Les nombres sur fond bleu sont premiers avec ${n}.</p><div class="residue-list">${Array.from({length:Number(n)},(_,i)=>{let k=BigInt(i+1);return `<span class="${M.egcd(k,n).g===1n?'coprime':''}">${k}</span>`;}).join('')}</div>`:`<p>Ce sont les entiers qui ne sont divisibles par aucun des facteurs premiers de ${n}.</p>`)}</div>`;}
function rsaResult(){const k=rsaKey;return answer('VOS CLÉS SONT PRÊTES',`n = ${k.n}`,`p = ${k.p} et q = ${k.q} sont deux nombres premiers distincts.`)+`<div class="key-grid"><div class="key"><small>CLÉ PUBLIQUE (n, e)</small><p>(${k.n}, ${k.e})</p></div><div class="key"><small>CLÉ PRIVÉE (n, d)</small><p>(${k.n}, ${k.d})</p></div></div><div class="steps">${step('Calculer le module',eq(`n = p × q = ${k.p} × ${k.q} = ${k.n}`))}${step('Calculer l’indicatrice',eq(`φ(n) = (p − 1)(q − 1) = ${k.t}`))}${step('Trouver la clé privée',eq(`d ≡ e<sup>−1</sup> (mod φ(n)) ≡ <strong>${k.d}</strong>`)+`<p>${k.e} × ${k.d} ≡ 1 (mod ${k.t}). C’est l’inverse modulaire !</p>`)}</div><div id="message-result"></div><p class="small-note">RSA pédagogique : petits nombres et chiffrement sans bourrage. Pour comprendre les maths, pas pour protéger de vraies données.</p>`;}
function makeKeys(){rsaKey=M.keys(val('p'),val('q'),val('e'));$('#result').innerHTML=rsaResult();}
function crypt(action){try{makeKeys();const k=rsaKey,mode=$('#mode').value,raw=$('#message').value;if(!raw.trim())throw Error('Saisissez un message ou un nombre.');let numbers,output,description;if(action==='encrypt'){
 if(mode==='text'){if(k.n<=255n)throw Error('Pour le texte UTF-8, choisissez p et q avec n > 255 (par exemple 61 et 53).');if(raw.length>500)throw Error('Limitez le message à 500 caractères.');numbers=Array.from(new TextEncoder().encode(raw),x=>BigInt(x));description='Le texte est encodé en octets UTF-8. Chaque octet m est chiffré séparément.';}else{numbers=[M.integer(raw,'Message')];description='Le message est un entier compris entre 0 et n − 1.';}
 if(numbers.some(m=>m<0n||m>=k.n))throw Error(`Le message numérique doit vérifier 0 ≤ m < ${k.n}.`);output=numbers.map(m=>M.pow(m,k.e,k.n));
 $('#message-result').innerHTML=`<h3 class="subhead">MESSAGE CHIFFRÉ</h3><p class="small-note">${description}</p><div class="answer"><div class="cipher">${output.join(' ')}</div></div><p class="small-note">c = m<sup>e</sup> mod n. Premier bloc : ${numbers[0]}<sup>${k.e}</sup> mod ${k.n} = ${output[0]}.</p><button class="secondary" id="use-cipher">Reprendre ce résultat pour déchiffrer ↓</button>`;$('#use-cipher').onclick=()=>{$('#message').value=output.join(' ');crypt('decrypt');};
 }else{let parts=raw.trim().split(/[\s,;]+/);if(parts.length>2000)throw Error('Maximum 2 000 blocs.');if(mode==='number'&&parts.length!==1)throw Error('Le mode Nombre attend un seul bloc chiffré.');numbers=parts.map(s=>M.integer(s,'Bloc chiffré'));if(numbers.some(c=>c<0n||c>=k.n))throw Error(`Chaque bloc doit être compris entre 0 et ${k.n-1n}.`);output=numbers.map(c=>M.pow(c,k.d,k.n));let decoded;if(mode==='text'){if(output.some(v=>v>255n))throw Error('Le résultat ne correspond pas à des octets UTF-8. Vérifiez les clés ou passez au mode Nombre.');try{decoded=new TextDecoder('utf-8',{fatal:true}).decode(Uint8Array.from(output,Number));}catch{throw Error('Texte UTF-8 invalide. Vérifiez les clés et les blocs chiffrés.');}}else decoded=output[0].toString();$('#message-result').innerHTML=`<h3 class="subhead">MESSAGE DÉCHIFFRÉ</h3><div class="answer"><div class="result-text">${esc(decoded)}</div></div><p class="small-note">m = c<sup>d</sup> mod n. Premier bloc : ${numbers[0]}<sup>${k.d}</sup> mod ${k.n} = ${output[0]}.</p>`;}
 }catch(err){showError(err);}}
function mount(name){view=config[name]?name:'home';const home=view==='home';$('#home-view').hidden=!home;$('#calculator-view').hidden=home;$('#home-link').classList.toggle('active',home);if(home)return;const c=config[view];$('#title').textContent=c.title;$('#crumb').textContent=c.title;$('#intro-text').textContent=c.text;document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});
 let html='';if(view==='inverse')html=`<form id="calc"><div class="field-row">${field('a','Le nombre a','L’entier à inverser','17')}${field('n','Le module n','Un entier ≥ 2','43')}</div><p class="math-note">On cherche un entier x tel que<br><strong>a × x ≡ 1 (mod n).</strong></p>${submit('Trouver l’inverse')}${examples([['3 ; 7','3,7'],['17 ; 43','17,43'],['Sans inverse','2,6']])}</form>`;
 if(view==='euclide')html=`<form id="calc"><div class="field-row">${field('a','Premier entier a','Positif, négatif ou nul','252')}${field('b','Second entier b','Positif, négatif ou nul','105')}</div><p class="math-note">Le dernier reste non nul est le PGCD. L’algorithme étendu donne les coefficients de Bézout.</p>${submit('Calculer & comprendre')}${examples([['252 ; 105','252,105'],['−17 ; 5','-17,5'],['35 ; 12','35,12']])}</form>`;
 if(view==='euler')html=`<form id="calc">${field('n','Le nombre n','De 1 à 1 000 000 000 000','72')}<p class="math-note">φ(n) compte les entiers de 1 à n premiers avec n.</p>${submit('Calculer φ(n)')}${examples([['φ(12)','12'],['φ(72)','72'],['φ(360)','360']])}</form>`;
 if(view==='rsa')html=`<form id="calc"><div class="field-row">${field('p','Nombre premier p','Entre 2 et 1 000 000','61')}${field('q','Nombre premier q','Distinct de p','53')}</div>${field('e','Exposant public e','1 < e < φ(n), premier avec φ(n)','17')}${submit('Construire les clés')}${examples([['61 × 53','61,53,17'],['11 × 13','11,13,7']])}</form><h3 class="subhead">VOTRE MESSAGE</h3><label for="mode">Format du message<select id="mode"><option value="text">Texte (encodage UTF-8)</option><option value="number">Nombre entier</option></select></label><label for="message">Message ou blocs chiffrés<small>Pour déchiffrer : séparez les blocs par des espaces.</small><textarea id="message" spellcheck="false">Bonjour !</textarea></label><div class="rsa-buttons"><button class="primary" id="encrypt">Chiffrer →</button><button class="secondary" id="decrypt">Déchiffrer</button></div>`;
 $('#form-area').innerHTML=html;$('#calc').addEventListener('submit',ev=>{ev.preventDefault();calculate();});document.querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>{const ids=view==='inverse'?['a','n']:view==='euclide'?['a','b']:view==='euler'?['n']:['p','q','e'];b.dataset.example.split(',').forEach((v,i)=>$('#'+ids[i]).value=v);if(view==='rsa'&&$('#p').value==='11'){$('#mode').value='number';$('#message').value='42';}calculate();});
 $('#calc').addEventListener('input',()=>{$('#result').innerHTML='<p class="small-note">Les entrées ont changé. Lancez le calcul pour actualiser la démonstration.</p>';rsaKey=null;});if(view==='rsa'){$('#encrypt').onclick=()=>crypt('encrypt');$('#decrypt').onclick=()=>crypt('decrypt');$('#mode').onchange=()=>{$('#message').value=$('#mode').value==='number'?'65':'Bonjour !';if(rsaKey)$('#result').innerHTML=rsaResult();};}
 $('#connection-title').textContent=view==='rsa'?'La clé privée est un inverse modulaire.':'L’inverse modulaire ouvre la porte à RSA.';$('#connection-text').textContent='Dans RSA, la clé privée d est l’inverse de e modulo φ(n). Ce que vous calculez ici est au cœur du déchiffrement.';$('#connection-link').innerHTML=view==='rsa'?'Revoir les inverses <span>→</span>':'Explorer RSA <span>→</span>';calculate();}
function calculate(){try{({inverse:renderInverse,euclide:renderEuclide,euler:renderEuler,rsa:makeKeys})[view]();}catch(e){showError(e);}}
$('#guide-open').onclick=$('#guide-side').onclick=()=>$('#guide').showModal();$('#guide-close').onclick=()=>$('#guide').close();
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{location.hash=b.dataset.view;});$('#connection-link').onclick=()=>{location.hash=view==='rsa'?'inverse':'rsa';};$('#print').onclick=()=>window.print();window.addEventListener('hashchange',()=>{mount(location.hash.slice(1));window.scrollTo(0,0);});mount(location.hash.slice(1));
